#!/usr/bin/env bash
# Builds and signs the Android APK from a project generated by generate-project.cjs.
# Usage: deploy/android/build-apk.sh <project-dir> <output.apk>
# Needs: JDK 17+ on PATH or JAVA_HOME, ANDROID_HOME with build-tools 36.1.0,
#        KEYSTORE_PATH (PKCS12, alias "kitchenstorage") and KEYSTORE_PASSWORD.
set -euo pipefail

PROJECT="${1:?project directory}"
OUTPUT="${2:?output apk path}"
BUILD_TOOLS="${ANDROID_HOME:?ANDROID_HOME is not set}/build-tools/36.1.0"
: "${KEYSTORE_PATH:?KEYSTORE_PATH is not set}"
: "${KEYSTORE_PASSWORD:?KEYSTORE_PASSWORD is not set}"

(cd "$PROJECT" && chmod +x gradlew && ./gradlew --no-daemon --quiet assembleRelease)

UNSIGNED="$PROJECT/app/build/outputs/apk/release/app-release-unsigned.apk"
ALIGNED="$(mktemp -d)/aligned.apk"
trap 'rm -rf "$(dirname "$ALIGNED")"' EXIT
"$BUILD_TOOLS/zipalign" -p -f 4 "$UNSIGNED" "$ALIGNED"
# The password is passed through the environment, never on the command line.
"$BUILD_TOOLS/apksigner" sign --ks "$KEYSTORE_PATH" --ks-key-alias kitchenstorage \
  --ks-pass env:KEYSTORE_PASSWORD --key-pass env:KEYSTORE_PASSWORD --out "$OUTPUT" "$ALIGNED"
"$BUILD_TOOLS/apksigner" verify --print-certs "$OUTPUT" | grep -E 'Signer #1 certificate (DN|SHA-256)'
rm -f "$OUTPUT.idsig"
